import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"Inquiry-based Learning","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-based.md","filePath":"ideas/inquiry-based.md"}'),r={name:"ideas/inquiry-based.md"};function o(g,n,c,e,u,m){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="inquiry-based-learning" tabindex="-1">Inquiry-based Learning <a class="header-anchor" href="#inquiry-based-learning" aria-label="Permalink to &quot;Inquiry-based Learning&quot;">​</a></h1><p>Trên trang này# Inquiry-based Learning <a href="#inquiry-based-learning">​</a> Bắt đầu bằng một câu hỏi, không bằng một câu trả lời. Learner tự tìm hiểu, thử, sai, rồi rút ra kết luận — thay vì nhận kết luận có sẵn rồi đi làm bài tập áp dụng.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Học sinh thuộc công thức nhưng không biết công thức đó từ đâu ra, dùng để làm gì, và khi nào thì không dùng được. Đổi cách hỏi một chút là bó tay — vì thứ được học là <em>quy trình</em>, không phải <em>nguyên tắc</em>. Inquiry đảo ngược thứ tự: gặp hiện tượng trước, tìm hiểu, rồi mới đến khái niệm. Kết luận đến sau cùng, và learner tham gia vào việc tạo ra nó.</p><h2 id="vi-du-cu-the-​" tabindex="-1">Ví dụ cụ thể <a href="#vi-du-cu-the">​</a> <a class="header-anchor" href="#vi-du-cu-the-​" aria-label="Permalink to &quot;Ví dụ cụ thể [​](#vi-du-cu-the)&quot;">​</a></h2><p><strong>Cách thông thường:</strong> Thầy nêu định lý Pythagoras, chứng minh, cho 20 bài áp dụng. <strong>Cách inquiry:</strong> Đưa cho học sinh nhiều tam giác vuông với số đo khác nhau, bảo đo và ghi lại ba cạnh. Hỏi: có quan hệ nào giữa ba số này không? Học sinh mò, thử cộng, thử nhân, thất bại vài lần. Ai đó thử bình phương. Cả lớp kiểm tra lại trên các tam giác khác. Định lý xuất hiện — và nó xuất hiện như <em>thứ họ tìm ra</em>, không phải thứ được thông báo. Cùng một định lý, nhưng đứa trẻ trong lớp thứ hai hiểu định lý đó là <strong>một quy luật có thật trong thế giới</strong>, chứ không phải một dòng cần nhớ.</p><h2 id="bon-muc-khong-phai-mot-​" tabindex="-1">Bốn mức, không phải một <a href="#bon-muc-khong-phai-mot">​</a> <a class="header-anchor" href="#bon-muc-khong-phai-mot-​" aria-label="Permalink to &quot;Bốn mức, không phải một [​](#bon-muc-khong-phai-mot)&quot;">​</a></h2><p>Đây là chỗ hay bị bỏ qua, và cũng là nguồn gốc của hầu hết thất bại khi áp dụng: MứcCâu hỏi từ đâuCách làm từ đâuKết luận từ đâu<strong>Xác nhận</strong>ThầyThầyĐã biết trước<strong>Có dẫn dắt</strong>ThầyThầyLearner tự rút ra<strong>Có hướng dẫn</strong>ThầyLearner tự nghĩLearner tự rút ra<strong>Mở</strong>LearnerLearnerLearnerNgười mới bắt đầu cần mức 1–2. Nhảy thẳng vào mức 4 với một learner chưa có nền gần như luôn thất bại — và thất bại đó thường bị quy nhầm cho phương pháp.</p><h2 id="đieu-kien-đe-no-hoat-đong-​" tabindex="-1">Điều kiện để nó hoạt động <a href="#đieu-kien-đe-no-hoat-đong">​</a> <a class="header-anchor" href="#đieu-kien-đe-no-hoat-đong-​" aria-label="Permalink to &quot;Điều kiện để nó hoạt động [​](#đieu-kien-đe-no-hoat-đong)&quot;">​</a></h2><p><strong>Phải có nền.</strong> Không thể truy vấn về thứ mình không biết gì. Một học sinh chưa biết nhân chia không thể &quot;khám phá&quot; định lý Pythagoras — em ấy chỉ ngồi loay hoay. <strong>Phải có thời gian.</strong> Inquiry chậm hơn nhiều so với giảng trực tiếp. Một tiết học có thể chỉ ra được một khái niệm. <strong>Phải có người dẫn giỏi.</strong> Biết khi nào để học sinh vật lộn thêm, khi nào đưa gợi ý, khi nào dừng lại vì cả lớp đang đi lạc — đây là kỹ năng khó, khó hơn hẳn việc giảng bài. <strong>Phải chốt lại.</strong> Inquiry mà không có bước tổng kết rõ ràng sẽ để lại một lớp học với những kết luận sai mà ai cũng tự tin. Đây là rủi ro thật và hay xảy ra.</p><h2 id="khi-no-phan-tac-dung-​" tabindex="-1">Khi nó phản tác dụng <a href="#khi-no-phan-tac-dung">​</a> <a class="header-anchor" href="#khi-no-phan-tac-dung-​" aria-label="Permalink to &quot;Khi nó phản tác dụng [​](#khi-no-phan-tac-dung)&quot;">​</a></h2><p><strong>Với người mới hoàn toàn.</strong> Có bằng chứng nhất quán rằng học sinh chưa có nền học kém hơn khi bị thả vào khám phá tự do so với khi được hướng dẫn trực tiếp. Trí nhớ làm việc của họ bị tiêu hết vào việc mò mẫm. <strong>Khi thời gian gấp.</strong> Còn ba tuần trước kỳ thi thì đây không phải lúc để khám phá. <strong>Với nội dung thuần quy ước.</strong> Không có gì để khám phá về việc &quot;tiếng Anh viết thứ Hai là Monday&quot;. Có những thứ chỉ cần được dạy thẳng.</p><h2 id="nemo12-dung-no-o-đau-​" tabindex="-1">Nemo12 dùng nó ở đâu <a href="#nemo12-dung-no-o-đau">​</a> <a class="header-anchor" href="#nemo12-dung-no-o-đau-​" aria-label="Permalink to &quot;Nemo12 dùng nó ở đâu [​](#nemo12-dung-no-o-đau)&quot;">​</a></h2><p>Ở các hoạt động <strong>Khám phá</strong> trong phòng lab — nơi learner tương tác với một mô hình, kéo thả, thay đổi tham số, và tự thấy quy luật hiện ra trước khi bất kỳ khái niệm nào được nêu tên. Quan trọng: hoạt động Khám phá chỉ xuất hiện <strong>khi bài học đó thật sự có thứ để khám phá</strong>, và thường ở mức 2 hoặc 3 — có khung dẫn dắt, không thả trôi. Sau khám phá luôn có bước chốt lại khái niệm bằng ngôn ngữ chính xác. Ở nhà Khi con hỏi một câu, thử hỏi ngược lại trước khi trả lời: <em>&quot;Con nghĩ sao?&quot;</em> — rồi mới bổ sung. Mất thêm hai phút, nhưng nó là toàn bộ tinh thần của inquiry, và nó cũng cho bạn biết con đang nghĩ gì.</p><h2 id="xem-mot-tiet-inquiry-that-​" tabindex="-1">Xem một tiết inquiry thật <a href="#xem-mot-tiet-inquiry-that">​</a> <a class="header-anchor" href="#xem-mot-tiet-inquiry-that-​" aria-label="Permalink to &quot;Xem một tiết inquiry thật [​](#xem-mot-tiet-inquiry-that)&quot;">​</a></h2><p>Mọi điều ở trên vẫn còn trừu tượng cho tới khi nhìn thấy một tiết học cụ thể. Nhóm demo dưới đây viết ra đầy đủ ba bài học cho mỗi môn, theo đúng khung IB — kèm từng câu hỏi dẫn của giáo viên và từng chỗ học sinh được để cho bế tắc. <a href="/ideas/inquiry-ib/">**Demo: IB dạy inquiry thế nào →**24 bài học đầy đủ, tám môn, kèm cách chấm theo bốn tiêu chí.</a>Inquiry mạnh khi learner đã có nền và có thời gian. Với người mới và thời gian gấp, dạy thẳng vẫn tốt hơn — điều đó không có gì đáng xấu hổ. <a href="/ideas/competency-based">Competency-based Education →</a></p>',16)])])}const l=h(r,[["render",o]]);export{d as __pageData,l as default};
